using System.Text.Json;
namespace FacialPresets;
public sealed class FacialKey {public Guid Id{get;set;}=Guid.NewGuid();public double Time{get;set;}public string Interpolation{get;set;}="Linear";public Preset State{get;set;}=new();}
public sealed class FacialClip {
 public int SchemaVersion{get;set;}=1;public Guid Id{get;set;}=Guid.NewGuid();public string Name{get;set;}="새 클립";public string Profile{get;set;}="vanilla";public double Duration{get;set;}=2;public List<string> RequiredResources{get;set;}=[];public List<FacialKey> Keys{get;set;}=[];
 public Preset Evaluate(double time){var result=new Preset{Profile=Profile,Name=Name,Channels=new(),RequiredResources=[..RequiredResources]};if(!double.IsFinite(time)||time<0||time>Duration)return result;var keys=Keys.OrderBy(k=>k.Time).ToArray();var a=keys.LastOrDefault(k=>k.Time<=time);if(a==null)return result;result=FacialTimeline.Copy(a.State);result.RequiredResources=result.RequiredResources.Concat(RequiredResources).Distinct().ToList();var b=keys.FirstOrDefault(k=>k.Time>time);if(b==null||a.Interpolation=="Hold")return result;double alpha=(time-a.Time)/(b.Time-a.Time);
  foreach(var (channel,c) in result.Channels){if(!b.State.Channels.TryGetValue(channel,out var right))continue;var nextById=right.Morphs.ToDictionary(n=>(n.Backend,n.Id));foreach(var m in c.Morphs){if(m.Enabled&&nextById.TryGetValue((m.Backend,m.Id),out var next)&&next.Enabled)m.Strength+=(next.Strength-m.Strength)*alpha;}}return result;
 }
}
public static class FacialClipFile {
 static readonly JsonSerializerOptions Options=new(){PropertyNamingPolicy=JsonNamingPolicy.CamelCase,PropertyNameCaseInsensitive=true,WriteIndented=true};
 public static void Validate(FacialClip c){if(c.SchemaVersion!=1||c.Id==Guid.Empty||string.IsNullOrWhiteSpace(c.Name)||c.Name.Length>200||c.Profile is not ("vanilla" or "erin")||!double.IsFinite(c.Duration)||c.Duration<=0||c.Duration>600||c.Keys==null||c.Keys.Count>2048||c.RequiredResources==null)throw new InvalidDataException("클립 형식·길이가 잘못되었습니다.");var names=new Dictionary<string,string>();var times=new HashSet<double>();var ids=new HashSet<Guid>();foreach(var k in c.Keys){if(k==null||k.Id==Guid.Empty||!double.IsFinite(k.Time)||k.Time<0||k.Time>c.Duration||!times.Add(k.Time)||!ids.Add(k.Id)||k.Interpolation is not ("Hold" or "Linear")||k.State==null)throw new InvalidDataException("키프레임 시간·ID·보간이 잘못되었거나 중복입니다.");PresetFile.Validate(k.State);foreach(var m in k.State.Channels.Values.SelectMany(ch=>ch.Morphs).Where(m=>m.Backend=="MFEE")){if(names.TryGetValue(m.Id,out var name)&&name!=m.Name)throw new InvalidDataException("같은 MFEE 식별자에 서로 다른 모프 이름이 지정되었습니다.");names[m.Id]=m.Name;}if(k.State.Profile!=c.Profile)throw new InvalidDataException("키와 클립 프로필이 다릅니다.");}}
 public static FacialClip Load(string path){if(new FileInfo(path).Length>8*1024*1024)throw new InvalidDataException("클립 파일이 너무 큽니다.");var text=File.ReadAllText(path);using var j=JsonDocument.Parse(text);foreach(var key in new[]{"schemaVersion","id","name","profile","duration","keys"})if(j.RootElement.ValueKind!=JsonValueKind.Object||!j.RootElement.TryGetProperty(key,out _))throw new InvalidDataException("클립 필수 필드가 없습니다.");JsonShape.Clip(j.RootElement);var c=JsonSerializer.Deserialize<FacialClip>(text,Options)??throw new InvalidDataException();Validate(c);return c;}
 public static void Save(string path,FacialClip c){Validate(c);var temp=path+Guid.NewGuid()+".tmp";try{var text=JsonSerializer.Serialize(c,Options);if(System.Text.Encoding.UTF8.GetByteCount(text)>8*1024*1024)throw new InvalidDataException("클립이 너무 큽니다.");File.WriteAllText(temp,text);File.Move(temp,path,true);}finally{if(File.Exists(temp))File.Delete(temp);}}
}
